import React from "react";
import {
  FaCode,
  FaAward,
  FaBriefcase,
  FaUsers,
  FaComments,
  FaLightbulb,
  FaCogs,
  FaUsersCog,
  FaClock,
  FaBrain
} from "react-icons/fa";

const Skills = () => {
  return (
    <section className="skills-page">

      {/* BACKGROUND EFFECTS */}
      <div className="glow"></div>
      <div className="grid-bg"></div>

      {/* HEADER */}
      <div className="header">
        <h1>Skills & Engineering Stack</h1>
        <p>A structured overview of my technical abilities, certifications, and learning journey.</p>
      </div>

      {/* MAIN LAYOUT */}
      <div className="layout">

        {/* LEFT - SKILL TIMELINE */}
        <div className="timeline">

          <div className="timeline-item">
            <div className="dot"></div>
            <div>
              <h3><FaCode /> Technical Skills</h3>
              <p>Java, React.js, Spring Boot, MySQL, HTML, CSS, JavaScript</p>
            </div>
          </div>

          <div className="timeline-item">
            <div className="dot"></div>
            <div>
              <h3><FaAward /> Certifications</h3>
              <p>
                Java – NPTEL <br />
                Data Science for Engineers – NPTEL <br />
                SQL – HackerRank <br />
                Python – SoloLearn
              </p>
            </div>
          </div>

        </div>

        {/* RIGHT - EXPERIENCE CARDS */}
        <div className="cards">

          <div className="card">
            <h3><FaBriefcase /> Internship - Full Stack Java</h3>
            <p>
              Worked on a Student Portal Management System using Spring Boot.
              Built REST APIs, backend logic, and database integration with frontend support.
            </p>
          </div>

          <div className="card">
            <h3><FaBriefcase /> Internship - Data Analytics</h3>
            <p>
              Completed internship in Data Analytics using Power BI.
              Built interactive dashboards, cleaned datasets, and converted raw data into insights.
              Improved skills in visualization, reporting, and decision-based analytics.
            </p>
          </div>

        </div>
      </div>

      {/* SOFT SKILLS */}
      <div className="soft">

        <h2>Soft Skills</h2>

        <div className="chips">
          <span><FaUsers /> Teamwork</span>
          <span><FaComments /> Communication</span>
          <span><FaLightbulb /> Problem Solving</span>
          <span><FaCogs /> Adaptability</span>
          <span><FaBrain /> Creativity</span>
          <span><FaUsersCog /> Leadership</span>
          <span><FaClock /> Time Management</span>
        </div>

      </div>

      {/* STYLE */}
      <style>{`

        .skills-page{
          min-height:100vh;
          padding:40px 10%;
          font-family:"Poppins",sans-serif;
          background: radial-gradient(circle at top,#0b1220,#050816);
          color:white;
          position:relative;
          overflow:hidden;
        }

        /* BACKGROUND */
        .glow{
          position:absolute;
          width:500px;
          height:500px;
          background:radial-gradient(circle,#38BDF8 0%,transparent 70%);
          top:-200px;
          right:-150px;
          filter:blur(60px);
          opacity:0.2;
        }

        .grid-bg{
          position:absolute;
          inset:0;
          background-image: linear-gradient(rgba(56,189,248,0.05) 1px, transparent 1px),
                            linear-gradient(90deg, rgba(56,189,248,0.05) 1px, transparent 1px);
          background-size:50px 50px;
          opacity:0.3;
          pointer-events:none;
        }

        /* HEADER */
        .header{
          text-align:center;
          margin-bottom:40px;
        }

        .header h1{
          font-size:42px;
          color:#38BDF8;
        }

        .header p{
          color:#94a3b8;
          margin-top:8px;
        }

        /* LAYOUT */
        .layout{
          display:grid;
          grid-template-columns:1fr 1fr;
          gap:40px;
        }

        /* TIMELINE */
        .timeline{
          position:relative;
          padding-left:20px;
        }

        .timeline::before{
          content:"";
          position:absolute;
          left:8px;
          top:0;
          bottom:0;
          width:2px;
          background:#38BDF8;
          opacity:0.4;
        }

        .timeline-item{
          display:flex;
          gap:15px;
          margin-bottom:30px;
        }

        .dot{
          width:12px;
          height:12px;
          background:#38BDF8;
          border-radius:50%;
          margin-top:6px;
          box-shadow:0 0 10px #38BDF8;
        }

        .timeline-item h3{
          color:#38BDF8;
          display:flex;
          align-items:center;
          gap:8px;
          margin-bottom:6px;
        }

        .timeline-item p{
          color:#cbd5e1;
          line-height:1.6;
        }

        /* CARDS */
        .cards{
          display:flex;
          flex-direction:column;
          gap:20px;
        }

        .card{
          padding:20px;
          border-radius:16px;
          background:rgba(255,255,255,0.04);
          border:1px solid rgba(56,189,248,0.2);
          backdrop-filter:blur(8px);
          transition:0.3s;
        }

        .card:hover{
          transform:translateY(-6px);
          border-color:#38BDF8;
          box-shadow:0 0 25px rgba(56,189,248,0.2);
        }

        .card h3{
          color:#38BDF8;
          margin-bottom:10px;
          display:flex;
          align-items:center;
          gap:8px;
        }

        .card p{
          color:#cbd5e1;
          line-height:1.6;
        }

        /* SOFT SKILLS */
        .soft{
          margin-top:50px;
          text-align:center;
        }

        .soft h2{
          color:#38BDF8;
          margin-bottom:20px;
        }

        .chips{
          display:flex;
          flex-wrap:wrap;
          justify-content:center;
          gap:12px;
        }

        .chips span{
          padding:8px 14px;
          border-radius:20px;
          background:rgba(56,189,248,0.1);
          border:1px solid rgba(56,189,248,0.3);
          color:#cbd5e1;
          display:flex;
          align-items:center;
          gap:6px;
          font-size:14px;
        }

        /* RESPONSIVE */
        @media(max-width:900px){
          .layout{
            grid-template-columns:1fr;
          }
        }

      `}</style>

    </section>
  );
};

export default Skills;
